mapper.select:
select cr.id, cr.user_id, u1.username, cr.comment_id as commentId, c.content as commentContent, c.user_id as commentUserId, u2.username as commentUsername, cr.report_time, cr.report_reason, cr.status, cr.reviewer_id, a.name as reviewer_name, cr.review_time, cr.review_result, cr.review_reason from comment_report cr left join user u1 on cr.user_id = u1.id left join comment c on cr.comment_id = c.id left join user u2 on c.user_id = u2.id left join auditor a on cr.reviewer_id = a.id
and cr.status = #{status}
and cr.user_id = #{userId}
and cr.comment_id = #{commentId}
and cr.reviewer_id = #{reviewerId}
order by cr.report_time desc
